func renderWallpaper(ctx context.Context, req render.WallpaperRequest) (*WallpaperOutput, error) {
	start := time.Now()
	res, err := render.Render(ctx, req)
	if err != nil {
		var ie *render.InputError
		var ue *render.UpstreamError
		switch {
		case errors.As(err, &ie):
			return nil, huma.Error422UnprocessableEntity(ie.Msg)
		case errors.As(err, &ue):
			return nil, huma.Error502BadGateway("fetching the background image failed: " + ue.Error())
		}
		return nil, err
	}
	return &WallpaperOutput{
		ContentType:  res.ContentType,
		CacheControl: "no-store",
		Size:         fmt.Sprintf("%dx%d", res.Width, res.Height),
		Device:       res.Device,
		RenderMs:     time.Since(start).Milliseconds(),
		Credit:       asciiHeader(res.BingCredit),
		Body:         res.Image,
	}, nil
}

func trimPad(s string) string {
	for len(s) > 0 && s[len(s)-1] == '=' {
		s = s[:len(s)-1]
	}
	return s
}

// asciiHeader drops characters that are not safe in an HTTP header value.
func asciiHeader(s string) string {
	b := make([]byte, 0, len(s))
	for _, r := range s {
		switch {
		case r == '©':
			b = append(b, "(c)"...)
		case r >= 0x20 && r < 0x7f:
			b = append(b, byte(r))
		}
	}
	return string(b)
}
